import sys
import re

def validate_int(s):
    if not re.fullmatch(r'(-?\d+)', s):
        return False
    num = int(s)
    return -2147483648 <= num <= 2147483647

def validate_bool(s):
    return s == 'true' or s == 'false'

def validate_value(value, type_):
    if type_ == 'int':
        return validate_int(value)
    elif type_ == 'bool':
        return validate_bool(value)
    elif type_ == 'string':
        return True
    return False

def main():
    data = sys.stdin.read().splitlines()
    idx = 0

    # Parse schema
    K = int(data[idx])
    idx += 1
    schema = []
    schema_map = {}
    for i in range(K):
        parts = data[idx].split()
        idx += 1
        key = parts[0]
        type_ = parts[1]
        required = parts[2] == 'yes'
        default = parts[3] if len(parts) > 3 else '-'
        schema.append({
            'key': key,
            'type': type_,
            'required': required,
            'default': default,
            'index': i
        })
        schema_map[key] = schema[-1]

    # Initialize effective config
    config = {}
    for entry in schema:
        if entry['default'] != '-':
            if validate_value(entry['default'], entry['type']):
                config[entry['key']] = entry['default']
            else:
                # Optional: treat invalid default as error
                pass

    # Parse layers
    L = int(data[idx])
    idx += 1
    errors = []

    for _ in range(L):
        layer_parts = data[idx].split()
        idx += 1
        layer_name = layer_parts[0]
        N = int(layer_parts[1])

        for directive_idx in range(1, N + 1):
            line = data[idx].strip()
            idx += 1

            if not line:
                errors.append(f"layer {layer_name} directive {directive_idx}: malformed directive")
                continue

            if line.endswith('!'):
                key = line[:-1].strip()
                if not key:
                    errors.append(f"layer {layer_name} directive {directive_idx}: malformed directive")
                    continue
                if key not in schema_map:
                    errors.append(f"layer {layer_name} directive {directive_idx}: unknown key {key}")
                else:
                    if key in config:
                        del config[key]
            elif '=' in line:
                parts = line.split('=', 1)
                key = parts[0].strip()
                value = parts[1].strip()
                if not key:
                    errors.append(f"layer {layer_name} directive {directive_idx}: malformed directive")
                    continue
                if key not in schema_map:
                    errors.append(f"layer {layer_name} directive {directive_idx}: unknown key {key}")
                else:
                    entry = schema_map[key]
                    if validate_value(value, entry['type']):
                        config[key] = value
                    else:
                        errors.append(f"layer {layer_name} directive {directive_idx}: invalid value for {key}")
            else:
                errors.append(f"layer {layer_name} directive {directive_idx}: malformed directive")

    # Check missing required keys
    for entry in schema:
        if entry['required'] and entry['key'] not in config:
            errors.append(f"missing required key {entry['key']}")

    # Output
    if not errors:
        print("OK")
        for entry in schema:
            if entry['key'] in config:
                print(f"{entry['key']}={config[entry['key']]}")
    else:
        print(f"ERROR {len(errors)}")
        for error in errors:
            print(error)

if __name__ == "__main__":
    main()
