import sys

def main():
    lines = sys.stdin.read().splitlines()
    if len(lines) < 2:
        return

    first_line = lines[0].strip()
    parts = first_line.split()
    if len(parts) != 2:
        return
    try:
        PAGE_WIDTH = int(parts[0])
        LABEL_WIDTH = int(parts[1])
    except ValueError:
        return

    second_line = lines[1].strip()
    parts = second_line.split()
    if len(parts) != 1:
        return
    try:
        N = int(parts[0])
    except ValueError:
        return
    if N < 0:
        return
    if N == 0:
        return

    MSG_WIDTH = PAGE_WIDTH - LABEL_WIDTH - 3
    if MSG_WIDTH < 1:
        MSG_WIDTH = 1

    for i in range(2, 2 + N):
        if i >= len(lines):
            break
        line = lines[i]
        tab_pos = line.find('\t')
        if tab_pos != -1:
            label = line[:tab_pos]
            message = line[tab_pos + 1:]
        else:
            label = line
            message = ""

        if len(label) > LABEL_WIDTH:
            if LABEL_WIDTH >= 1:
                label = label[:LABEL_WIDTH - 1] + '~'
            else:
                label = ""
        elif len(label) < LABEL_WIDTH:
            label = label.ljust(LABEL_WIDTH)
        else:
            label = label

        import re
        message = re.sub(r'\s+', ' ', message.strip())
        if not message:
            print(f"{label} | ")
            continue

        words = message.split(' ')
        current_line = []
        current_length = 0
        first_line = True

        for word in words:
            if not word:
                continue
            word_len = len(word)
            if word_len > MSG_WIDTH:
                if current_line:
                    flush_line(current_line, first_line, label, LABEL_WIDTH)
                    first_line = False
                    current_line = []
                    current_length = 0
                chunks = [word[j:j+MSG_WIDTH] for j in range(0, len(word), MSG_WIDTH)]
                for chunk in chunks:
                    if first_line:
                        print(f"{label} | {chunk}")
                        first_line = False
                    else:
                        print(f"{' ' * LABEL_WIDTH} | {chunk}")
            else:
                if current_line and current_length + 1 + word_len > MSG_WIDTH:
                    flush_line(current_line, first_line, label, LABEL_WIDTH)
                    first_line = False
                    current_line = [word]
                    current_length = word_len
                else:
                    if current_line:
                        current_line.append(' ')
                        current_length += 1
                    current_line.append(word)
                    current_length += word_len
        if current_line:
            flush_line(current_line, first_line, label, LABEL_WIDTH)

def flush_line(current_line, first_line, label, LABEL_WIDTH):
    line_text = ''.join(current_line)
    if first_line:
        print(f"{label} | {line_text}")
    else:
        print(f"{' ' * LABEL_WIDTH} | {line_text}")

if __name__ == "__main__":
    main()
