import sys
import re
from urllib.parse import urlparse

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    base_url = data[0].strip()
    allowed_exts = set(ext.strip().lower() for ext in data[1].split(','))
    n = int(data[2])
    references = [line.strip() for line in data[3:3+n]]

    parsed_base = urlparse(base_url)
    scheme = parsed_base.scheme.lower()
    host = parsed_base.hostname
    path = parsed_base.path

    if path.endswith('/'):
        base_dir = path
    else:
        last_slash = path.rfind('/')
        if last_slash == -1:
            base_dir = '/'
        else:
            base_dir = path[:last_slash + 1]

    base_prefix = f"{parsed_base.scheme}://{host}"

    for ref in references:
        if not ref:
            print("SKIP empty")
            continue

        query_pos = ref.find('?')
        frag_pos = ref.find('#')
        end_pos = min(query_pos, frag_pos) if query_pos != -1 and frag_pos != -1 else max(query_pos, frag_pos)
        if end_pos != -1:
            ref = ref[:end_pos]
        if not ref:
            print("SKIP empty")
            continue

        if ref.startswith('http://') or ref.startswith('https://'):
            parsed = urlparse(ref)
            ref_scheme = parsed.scheme.lower()
            ref_host = parsed.hostname.lower() if parsed.hostname else ''
            if ref_scheme != scheme or ref_host != host.lower():
                print("SKIP external")
                continue
            path_part = parsed.path
        elif ref.startswith('//'):
            parts = ref[2:].split('/', 1)
            ref_host = parts[0].lower()
            if ref_host != host.lower():
                print("SKIP external")
                continue
            path_part = '/' + parts[1] if len(parts) > 1 else '/'
        elif ref.startswith('/'):
            path_part = ref
        else:
            path_part = ref

        if path_part.startswith('/'):
            abs_path = path_part
        else:
            abs_path = base_dir + path_part

        segments = [seg for seg in abs_path.split('/') if seg]
        stack = []
        for seg in segments:
            if seg == '.':
                continue
            elif seg == '..':
                if stack:
                    stack.pop()
            else:
                stack.append(seg)
        normalized = '/' + '/'.join(stack)
        if normalized == '/':
            print("SKIP no_extension")
            continue

        filename = stack[-1] if stack else ''
        if not filename:
            print("SKIP no_extension")
            continue

        last_dot = filename.rfind('.')
        if last_dot <= 0:
            print("SKIP no_extension")
            continue

        ext = filename[last_dot+1:].lower()
        if ext not in allowed_exts:
            print("SKIP blocked_extension")
            continue

        print(f"OK {base_prefix}{normalized}")

if __name__ == "__main__":
    main()
